export const CATALOG_ERROR_CODES = [
  'invalid_shop_id',
  'shop_not_found',
  'catalog_unavailable',
  'catalog_read_failed',
  'method_not_allowed',
  'invalid_request',
  'authentication_required',
  'invalid_identity',
  'membership_required',
  'membership_inactive',
  'role_forbidden',
  'entity_not_found',
  'cross_shop_forbidden',
  'image_key_forbidden',
  'command_conflict',
  'command_failed',
  'storage_failed',
] as const;

export type CatalogErrorCodeV1 = (typeof CATALOG_ERROR_CODES)[number];

export interface CatalogErrorV1 {
  readonly schemaVersion: 1;
  readonly error: {
    readonly code: CatalogErrorCodeV1;
  };
